42	            if (file) {
43	                const varbitDef = (parse as any).varbits.read(file.buffer, this.cache);
44	                fs.writeFileSync(outPath, JSON.stringify(varbitDef, null, 2));
45	                console.log(`[GODHEAD] Resolved Varbit ${id}: BaseVar ${varbitDef.basevar}, ${varbitDef.bitsbins[0]}-${varbitDef.bitsbins[1]}`);
