1	import Database from 'better-sqlite3';
2	import { join } from 'path';
3	import { getSovereignRoot } from './SovereignPathResolver';
4	import { createLogger } from './logger';
5	
6	const logger = createLogger('rsmv_inspectorCacheDB');
7	
8	export interface GroundedEntity {
9	    entity_type: 'npc' | 'object';
10	    entity_id: number;
11	    entity_name?: string;
12	    x: number;
13	    y: number;        // renamed from z in some parsers — keeping consistent with RS coords
14	    z: number;
15	    plane: number;
16	    zone_id: number;
17	    varbit_flags?: Record<string, any>;   // any active varbits controlling this spawn
18	    is_morphic: boolean;                  // has "Actions" or varbit-controlled morph
19	    has_actions: boolean;
20	    material_flags?: { hasNormal: boolean; hasCompound: boolean }; // from taxonomic_synthesis
21	    learned_at?: string;
22	}
23	
24	export class rsmv_inspectorCacheDB {
25	    private db: Database.Database;
26	    private readonly dbPath: string;
27	
28	    constructor() {
29	        this.dbPath = join(getSovereignRoot(), 'memory', 'rsmv_inspector_cache.db');
30	        this.db = new Database(this.dbPath);
31	        this.initSchema();
32	        logger.info({ path: this.dbPath }, 'rsmv_inspector Cache DB initialized');
33	    }
34	
35	    private initSchema() {
36	        this.db.exec(`
37	            CREATE TABLE IF NOT EXISTS grounded_entities (
38	                id INTEGER PRIMARY KEY AUTOINCREMENT,
39	                entity_type TEXT NOT NULL,
40	                entity_id INTEGER NOT NULL,
41	                entity_name TEXT,
42	                x INTEGER NOT NULL,
43	                y INTEGER NOT NULL,
44	                z INTEGER NOT NULL,
45	                plane INTEGER NOT NULL,
46	                zone_id INTEGER NOT NULL,
47	                varbit_flags JSON,
48	                is_morphic BOOLEAN DEFAULT FALSE,
49	                has_actions BOOLEAN DEFAULT FALSE,
50	                material_flags JSON,
51	                learned_at DATETIME DEFAULT CURRENT_TIMESTAMP,
52	                UNIQUE(entity_type, entity_id, x, y, z, plane)
53	            );
54	
55	            CREATE INDEX IF NOT EXISTS idx_grounded_zone ON grounded_entities(zone_id);
56	            CREATE INDEX IF NOT EXISTS idx_grounded_entity ON grounded_entities(entity_type, entity_id);
57	        `);
58	
59	        logger.info('Grounded entities schema ready — coordinate-exact spatial nervous system online.');
60	    }
61	
62	    public insertGrounded(entity: GroundedEntity): void {
63	        const stmt = this.db.prepare(`
64	            INSERT OR REPLACE INTO grounded_entities 
65	            (entity_type, entity_id, entity_name, x, y, z, plane, zone_id, varbit_flags, is_morphic, has_actions, material_flags)
66	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
67	        `);
68	
69	        stmt.run(
70	            entity.entity_type,
