1	import * as THREE from 'three';
2	import { SovereignGroundingStream } from './SovereignGroundingStream';
3	import { RSMeshLoader } from './RSMeshLoader';
4	import { ThreejsSceneCache } from '../3d/modeltothree';
5	import { SovereignWorldLoader, CollisionTile } from './SovereignWorldLoader';
6	
7	export class RSSpatialManager {
8	  private grounding = new SovereignGroundingStream();
9	  public loader: RSMeshLoader;
10	  private loadedChunks = new Set<string>();
11	  private collisionCache = new Map<string, CollisionTile>();
12	  private loadedCollisionRegions = new Set<string>();
13	
14	  constructor(sceneCache: ThreejsSceneCache) {
15	    this.loader = new RSMeshLoader(sceneCache);
16	  }
17	
18	  async initialize(): Promise<void> {
19	    await this.grounding.initialize();
20	    console.log('[RSSpatialManager] Grounding stream initialized');
21	  }
22	
23	  public setCacheLoader(loader: any) {
24	    this.grounding.setCacheSubstrate(loader);
25	    SovereignWorldLoader.getInstance().setCacheSubstrate(loader);
26	  }
27	
28	  // Called from RSEngine tick — cheap after first pass (loadedChunks guards re-entry)
29	  async stream(avatarTileX: number, avatarTileZ: number, scene: THREE.Object3D, plane: number = 0): Promise<void> {
30	    // Hydrate collision cache for this region
31	    const rx = Math.floor(avatarTileX / 64);
32	    const rz = Math.floor(avatarTileZ / 64);
33	    const regionKey = `${rx}_${rz}`;
34	    if (!this.loadedCollisionRegions.has(regionKey)) {
35	      this.loadedCollisionRegions.add(regionKey);
36	      const truth = await SovereignWorldLoader.getInstance().loadRegionTruth(rx, rz);
37	      if (truth) {
38	        for (const [key, tile] of Object.entries(truth.collisionMatrix)) {
39	          this.collisionCache.set(key, tile);
40	        }
41	        console.log(`[RSSpatialManager] Collision cache hydrated for region [${rx}, ${rz}]: ${Object.keys(truth.collisionMatrix).length} tiles`);
42	      }
43	    }
44	
45	    const manifests = this.grounding.getStreamingManifests(avatarTileX, avatarTileZ, 208, plane);
46	
47	    for (const manifest of manifests) {
48	      if (this.loadedChunks.has(manifest.chunkKey)) continue;
49	      this.loadedChunks.add(manifest.chunkKey);
50	
51	      console.log(
52	        `[Spatial] Streaming ${manifest.chunkKey} ` +
53	        `(${manifest.zoneName ?? 'unnamed'}) — ` +
54	        `${manifest.entityIds.length} entities`
55	      );
56	
57	      // Non-blocking — don't await in the tick loop
58	      this.loader.loadManifest(manifest, scene).catch(err =>
59	        console.error(`[Spatial] loadManifest failed for ${manifest.chunkKey}:`, err)
60	      );
61	    }
62	  }
63	
64	  /**
65	   * Sovereign Collision Engine: Real walkability check from collision_matrix.
66	   */
67	  public isWalkable(tileX: number, tileZ: number): boolean {
68	    const floorX = Math.floor(tileX);
69	    const floorZ = Math.floor(tileZ);
70	    const key = `${floorX}_${floorZ}`;
71	    const tile = this.collisionCache.get(key);
72	    if (!tile) return true; // Unknown tiles default to passable (unmapped void)
73	    return tile.walkable;
74	  }
75	
76	  /**
77	   * Returns the full collision cache for overlay rendering.
78	   */
79	  public getCollisionMatrix(): Map<string, CollisionTile> {
80	    return this.collisionCache;
81	  }
82	
83	  /** Returns the full list of indexed chunk keys (useful for debug overlays) */
84	  getIndexedChunkKeys(): string[] {
85	    return Array.from(this.loadedChunks);
86	  }
87	}
